'use strict'

const pino = require('pino')

const styleCodes = {
  reset: {
    dim: '\x1b[22m',
    fg: '\x1b[39m',
    redBg: '\x1b[49m',
  },
  dim: '\x1b[2m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  green: '\x1b[32m',
  purple: '\x1b[35m',
  red: '\x1b[31m',
  redBg: '\x1b[41m',
  yellow: '\x1b[33m',
}

const levelLabels = Object.entries(pino.levels.labels).reduce((accum, [code, label]) => {
  accum[code] = accum[label] = label.toUpperCase()
  return accum
}, {})

const levelColors = {
  DEBUG: 'blue',
  ERROR: 'red',
  FATAL: 'redBg',
  INFO: 'green',
  TRACE: 'gray',
  WARN: 'yellow',
}

function applyNoStyle (_, str) {
  return str
}

function applyStyle (styleCode, str) {
  return styleCodes[styleCode] + str + (styleCodes.reset[styleCode] ?? styleCodes.reset.fg)
}

function prettifyLogObject (logObject, dataTransforms, colorEnabled) {
  const { time, level, name, caller, msg, hint, pid: _pid, hostname: _hostname, ...data } = logObject
  const stylize = colorEnabled ? applyStyle : applyNoStyle
  const levelLabel = levelLabels[level]
  const levelColor = levelColors[levelLabel]
  let result = `[${stylize('gray', formatTime(time))}] ${stylize(levelColor, levelLabel)}`
  if (name) result += ` (${name})`
  if (caller) result += ` <${caller}>`
  if (~msg.indexOf('\n')) {
    let lineIdx = 0
    for (const line of msg.split('\n')) {
      result += lineIdx++ ? `\n${line}` : `: ${stylize('cyan', line)}`
    }
  } else {
    result += `: ${stylize('cyan', msg)}`
  }
  if (hint) result += `\n${stylize('gray', stylize('dim', hint))}`
  if (isEmpty(data)) return result
  return result + '\n' + indent(prettifyLogData(data, dataTransforms, logObject, stylize)).join('\n')
}

function prettifyLogData (data, dataTransforms, logObject, stylize) {
  if (data.type === 'Error' && 'stack' in data) return data.stack.split('\n')
  const stylizeKey = stylize.bind(null, 'purple')
  if (dataTransforms == null || isEmpty(dataTransforms) || !Object.keys(data).some((k) => k in dataTransforms)) {
    return prettifyObject(data, stylizeKey)
  }
  const transformedData = {}
  for (const k in data) {
    transformedData[k] = k in dataTransforms ? dataTransforms[k](data[k], k, logObject) : data[k]
  }
  return prettifyObject(transformedData, stylizeKey)
}

function prettifyValue (val, stylizeKey) {
  if (!val || val === true) return val === '' ? '""' : '' + val
  if (val.constructor === Object) return prettifyObject(val, stylizeKey)
  if (Array.isArray(val)) {
    if (!val.length) return '[]'
    return val.reduce((lines, it) => {
      const prettified = prettifyValue(it, stylizeKey)
      if (Array.isArray(prettified)) {
        prettified.forEach((line, idx) => lines.push((idx ? (line ? '  ' : '') : '- ') + line))
      } else {
        lines.push('- ' + prettified)
      }
      return lines
    }, [])
  }
  return ~(val = (val.constructor === String ? val : val.toString()).trimEnd()).indexOf('\n') ? val.split('\n') : val
}

function prettifyObject (obj, stylizeKey) {
  const lines = []
  for (const [key, val] of Object.entries(obj)) {
    const prettified = prettifyValue(val, stylizeKey)
    if (Array.isArray(prettified)) {
      lines.push(stylizeKey(key + ':'))
      prettified.forEach((line) => lines.push(line ? '  ' + line : ''))
    } else {
      lines.push(stylizeKey(key + ':') + ' ' + prettified)
    }
  }
  return lines.length ? lines : '{}'
}

function indent (lines, w = 4) {
  const indentation = ' '.repeat(w)
  return lines.map((line) => (line ? indentation + line : line))
}

function formatTime (epoch) {
  const d = new Date(epoch)
  const pad = (n, w = 2) => String(n).padStart(w, '0')
  return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()) + '.' + pad(d.getMilliseconds(), 3)
}

function isEmpty (obj) {
  for (const _ in obj) return false
  return true
}

module.exports = prettifyLogObject
